<template>
  <div class="external-page">
    <el-form :model="query" inline class="query-form"><el-form-item label="外管账号"><el-input v-model="query.loginName" clearable placeholder="请输入" /></el-form-item><el-form-item label="关联 Woha ID"><el-input v-model="query.wohaChatNo" clearable placeholder="请输入 ChatNo" /></el-form-item><el-form-item label="角色"><el-select v-model="query.roleCode" clearable placeholder="请选择"><el-option v-for="item in roles" :key="item.value" :label="item.label" :value="item.value" /></el-select></el-form-item><el-form-item label="所属 SA"><el-input v-model="query.parentLoginName" clearable placeholder="请输入" /></el-form-item><el-form-item label="开通方式"><el-select v-model="query.openMethod" clearable placeholder="请选择"><el-option label="运营开通" value="运营开通" /><el-option label="下级新增" value="下级新增" /></el-select></el-form-item><el-button type="primary" @click="load">查询</el-button><el-button @click="resetQuery">重置</el-button></el-form>
    <div class="table-toolbar"><span class="section-title">外管账号</span><el-button type="primary" @click="openCreate">开通外管</el-button></div>
    <el-table v-loading="loading" :data="rows" border style="margin-top:16px"><el-table-column prop="loginName" label="外管" min-width="130" /><el-table-column label="关联 Woha ID" min-width="160"><template #default="{ row }">{{ row.wohaChatNo || '-' }}</template></el-table-column><el-table-column label="角色" min-width="115"><template #default="{ row }">{{ roleName(row.roleCode) }}</template></el-table-column><el-table-column label="上级" min-width="130"><template #default="{ row }">{{ row.parentLoginName || '-' }}</template></el-table-column><el-table-column label="直属下级" align="center" min-width="90"><template #default="{ row }">{{ row.subordinateCount || 0 }}</template></el-table-column><el-table-column label="团队公会" align="center" min-width="90"> <template #default="{ row }">{{ row.guildCount || 0 }}</template></el-table-column><el-table-column label="功能权限" align="center" min-width="100"><template #default="{ row }">{{ permissionCount(row.permissions) }} 项</template></el-table-column><el-table-column label="状态" min-width="80"><template #default="{ row }"><el-tag :type="row.status === '0' ? 'success' : 'info'">{{ row.status === '0' ? '正常' : '停用' }}</el-tag></template></el-table-column><el-table-column prop="openMethod" label="开通方式" min-width="110" /><el-table-column prop="createTime" label="开通时间" min-width="165" /><el-table-column label="操作" width="280" fixed="right"><template #default="{ row }"><el-button link type="primary" @click="openEdit(row)">编辑</el-button><el-button link type="primary" @click="openResetPassword(row)">重置密码</el-button><el-button link :type="row.status === '0' ? 'warning' : 'success'" @click="toggleStatus(row)">{{ row.status === '0' ? '停用' : '启用' }}</el-button><el-button link type="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table>
    <pagination v-show="total > 0" v-model:page="query.pageNum" v-model:limit="query.pageSize" :total="total" @pagination="load" />
    <el-dialog v-model="visible" :title="form.id ? '编辑外管账号' : '开通外管'" width="640px" destroy-on-close><el-form ref="formRef" :model="form" :rules="rules" label-width="130px"><el-form-item label="登录账号" prop="loginName"><el-input v-model="form.loginName" :disabled="Boolean(form.id)" /></el-form-item><el-form-item :label="form.id ? '新密码' : '登录密码'" prop="password"><el-input v-model="form.password" type="password" show-password :placeholder="form.id ? '留空则不修改' : ''" /></el-form-item><el-form-item label="姓名" prop="realName"><el-input v-model="form.realName" /></el-form-item><el-form-item label="关联 Woha ID" prop="wohaChatNo"><el-input v-model.number="form.wohaChatNo" placeholder="请输入 ChatNo" /></el-form-item><el-form-item label="角色" prop="roleCode"><el-select v-model="form.roleCode" @change="form.parentId = null"><el-option v-for="item in roles" :key="item.value" :label="item.label" :value="item.value" /></el-select></el-form-item><el-form-item v-if="form.roleCode !== 'SUPER_ADMIN'" label="上级外管账号 ID" prop="parentId"><el-input v-model.number="form.parentId" /></el-form-item><el-form-item label="所属大区" prop="regionId"><el-select v-model="form.regionId"><el-option v-for="item in regions" :key="item.value" :label="item.label" :value="item.value" /></el-select></el-form-item><el-form-item label="功能权限"><el-checkbox-group v-model="form.permissions"><el-checkbox v-for="item in permissions" :key="item.value" :label="item.value">{{ item.label }}</el-checkbox></el-checkbox-group></el-form-item></el-form><template #footer><el-button @click="visible = false">取消</el-button><el-button type="primary" @click="submit">保存</el-button></template></el-dialog>
  </div>
</template>

<script setup>
import { addExternalAccount, changeExternalAccountStatus, delExternalAccount, getExternalAccount, listExternalAccount, resetExternalAccountPassword, updateExternalAccount } from '@/api/external/manager'
import { ElMessageBox } from 'element-plus'
const roles = [{ value: 'SUPER_ADMIN', label: 'Super Admin' }, { value: 'BD_LEADER', label: 'BD Leader' }, { value: 'BD', label: 'BD' }]
const regions = [{ value: 1, label: '全球' }, { value: 2, label: '东南亚' }, { value: 3, label: '华语' }, { value: 4, label: '中东' }, { value: 5, label: '印度' }, { value: 6, label: '越南' }, { value: 7, label: '菲律宾' }]
const permissions = [{ value: 'VIEW_TEAM_GUILD', label: '查看团队与公会' }, { value: 'VIEW_GUILD_FLOW', label: '查看公会流水' }, { value: 'CREATE_SUBORDINATE', label: '新增下级' }, { value: 'CREATE_GUILD', label: '新建公会' }, { value: 'SEND_GIFT_PACK', label: '赠送礼包' }, { value: 'ASSIGN_CHAT_NO', label: '分配靓号' }, { value: 'EXECUTE_BAN', label: '执行封禁' }, { value: 'SUBMIT_REPORT', label: '提交举报' }, { value: 'EXPORT_DATA', label: '数据导出' }]
const loading = ref(false); const rows = ref([]); const total = ref(0); const visible = ref(false); const formRef = ref(); const query = reactive({ pageNum: 1, pageSize: 10, loginName: '', wohaChatNo: undefined, roleCode: undefined, parentLoginName: '', openMethod: undefined }); const form = reactive({}); const rules = { loginName: [{ required: true, message: '请输入登录账号', trigger: 'blur' }], password: [{ validator: (_, value, callback) => { if (!form.id && !value) callback(new Error('请输入登录密码')); else if (value && !/^(?=.*[A-Za-z])(?=.*\d).{8,50}$/.test(value)) callback(new Error('至少 8 位，且包含字母和数字')); else callback() }, trigger: 'blur' }], realName: [{ required: true, message: '请输入姓名', trigger: 'blur' }], wohaChatNo: [{ required: true, message: '请输入 Woha ChatNo', trigger: 'blur' }], roleCode: [{ required: true, message: '请选择角色', trigger: 'change' }], regionId: [{ required: true, message: '请选择大区', trigger: 'change' }] }
const roleName = value => roles.find(item => item.value === value)?.label || value; const regionName = value => regions.find(item => item.value === value)?.label || value
const permissionCount = value => value ? value.split(',').filter(Boolean).length : 0
async function load() { loading.value = true; try { const data = await listExternalAccount(query); rows.value = data.rows; total.value = data.total } finally { loading.value = false } }
function resetQuery() { Object.assign(query, { pageNum: 1, loginName: '', wohaChatNo: undefined, roleCode: undefined, parentLoginName: '', openMethod: undefined }); load() }
function openCreate() { Object.assign(form, { id: null, loginName: '', password: '', realName: '', wohaChatNo: undefined, roleCode: 'BD', parentId: undefined, regionId: 2, permissions: [] }); visible.value = true; nextTick(() => formRef.value?.clearValidate()) }
async function openEdit(row) { const data = await getExternalAccount(row.id); Object.assign(form, data.data, { password: '', permissions: data.data.permissions ? data.data.permissions.split(',').filter(Boolean) : [] }); visible.value = true; nextTick(() => formRef.value?.clearValidate()) }
function submit() { formRef.value.validate(async valid => { if (!valid) return; const data = { ...form }; if (data.id && !data.password) delete data.password; if (data.id) await updateExternalAccount(data.id, data); else await addExternalAccount(data); visible.value = false; load() }) }
async function toggleStatus(row) { await changeExternalAccountStatus(row.id, row.status === '0' ? '1' : '0'); load() }
async function remove(row) { await ElMessageBox.confirm(`确认删除外管账号 ${row.loginName}？`, '提示', { type: 'warning' }); await delExternalAccount(row.id); load() }
async function openResetPassword(row) { const { value } = await ElMessageBox.prompt('请输入新密码，至少 8 位且包含字母和数字', `重置 ${row.loginName} 的密码`, { inputType: 'password' }); await resetExternalAccountPassword(row.id, value); }
load()
</script>

<style scoped>
.external-page {
  box-sizing: border-box;
  padding: 20px;
}
.query-form { margin-bottom: 12px; }
.table-toolbar { display: flex; align-items: center; justify-content: space-between; }
.section-title { font-size: 16px; font-weight: 600; color: #303133; }
</style>
